'@
$bytes = [Convert]::FromBase64String(($data -replace '\s', ''))
$memory = [System.IO.MemoryStream]::new($bytes)
$gzip = [System.IO.Compression.GzipStream]::new($memory, [System.IO.Compression.CompressionMode]::Decompress)
$reader = [System.IO.StreamReader]::new($gzip, [System.Text.Encoding]::ASCII)
try {
    $frames = $reader.ReadToEnd().Split([char]12)
} finally {
    $reader.Dispose()
}

$fps = 30.0
$frameMs = 1000.0 / ($fps * $Speed)
$first = [Math]::Min($frames.Length - 1, [int][Math]::Floor($StartAt * $fps))
$last = if ($Duration -gt 0) {
    [Math]::Min($frames.Length, $first + [int][Math]::Ceiling($Duration * $fps))
} else {
    $frames.Length
}
$audioPlayer = $null
$audioStream = $null
if (-not $NoAudio) {
    if ($Speed -ne 1.0 -or $StartAt -ne 0.0) {
        throw 'Audio stays in sync only at normal speed from the beginning. Add -NoAudio for speed or start-time changes.'
    }
    $audioBytes = [Convert]::FromBase64String(($audioData -replace '\s', ''))
    $audioCompressed = [System.IO.MemoryStream]::new($audioBytes)
    $audioGzip = [System.IO.Compression.GzipStream]::new($audioCompressed, [System.IO.Compression.CompressionMode]::Decompress)
    $audioStream = [System.IO.MemoryStream]::new()
    try {
        $audioGzip.CopyTo($audioStream)
    } finally {
        $audioGzip.Dispose()
        $audioCompressed.Dispose()
    }
    $audioStream.Position = 0
    $audioPlayer = [System.Media.SoundPlayer]::new($audioStream)
    $audioPlayer.Load()
}
if (-not [Console]::IsOutputRedirected) {
    if (-not ([System.Management.Automation.PSTypeName]'BadAppleConsoleVT').Type) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class BadAppleConsoleVT {
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern IntPtr GetStdHandle(int handle);
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool GetConsoleMode(IntPtr handle, out uint mode);
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool SetConsoleMode(IntPtr handle, uint mode);
}
'@
    }
    $handle = [BadAppleConsoleVT]::GetStdHandle(-11)
    [uint32]$consoleMode = 0
    if (-not [BadAppleConsoleVT]::GetConsoleMode($handle, [ref]$consoleMode) -or
        -not [BadAppleConsoleVT]::SetConsoleMode($handle, ($consoleMode -bor 0x0005))) {
        throw 'This console cannot display ANSI animation.'
    }
}
$esc = [char]27
$displayHeight = 28
if (-not [Console]::IsOutputRedirected) {
    if ([Console]::WindowWidth -le 72 -or [Console]::WindowHeight -lt 16) {
        throw 'Terminal must be at least 73 columns by 16 rows.'
    }
    $displayHeight = [Math]::Min(28, [Console]::WindowHeight - 1)
}
$selectedRows = if ($displayHeight -lt 28) {
    @(for ($row = 0; $row -lt $displayHeight; $row++) {
        [int][Math]::Round($row * 27.0 / ($displayHeight - 1))
    })
} else { @() }
$clock = [System.Diagnostics.Stopwatch]::new()
try {
    [Console]::Write(([string]$esc + '[?25l' + [string]$esc + '[2J'))
    do {
        $deadline = 0.0
        if ($audioPlayer) { $audioPlayer.Play() }
        $clock.Restart()
        for ($i = $first; $i -lt $last; $i++) {
            $picture = $frames[$i]
            if ($displayHeight -lt 28) {
                $rows = $picture -split "`r`n"
                $picture = ($selectedRows | ForEach-Object { $rows[$_] }) -join "`r`n"
            }
            [Console]::Write(([string]$esc + '[H' + $picture + [string]$esc + '[J'))
            $deadline += $frameMs
            $remaining = $deadline - $clock.Elapsed.TotalMilliseconds
            if ($remaining -ge 1) {
                Start-Sleep -Milliseconds ([int][Math]::Floor($remaining))
            }
        }
    } while ($Loop)
} finally {
    if ($audioPlayer) {
        $audioPlayer.Stop()
        $audioPlayer.Dispose()
    }
    if ($audioStream) { $audioStream.Dispose() }
    [Console]::Write(([string]$esc + '[?25h' + [Environment]::NewLine))
}
